      maxSum = sum;
      bestCombination = comb;
    }
  }

  return bestCombination;
}

void _generateCombinations(List<int> nums, int k, List<int> current, int start) {
  if (current.length == k) {
    combinations.add(current.toList());
    return;
  }

  for (int i = start; i < nums.length; i++) {
    current.add(nums[i]);
    _generateCombinations(nums, k, current, i + 1);
    current.removeLast();
  }
}

